const $=id=>document.getElementById(id);let sim=new Simulation(),selected=0,paused=false,guided=false,demoStart=0;
const fmt=t=>`T+${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;
const color=s=>s==='Healthy'?'green':s==='Critical'||s==='Offline'?'red':'amber';
function reset(){sim=new Simulation();paused=false;guided=false;render();}
function step(){if(paused)return;if(guided){const elapsed=sim.time-demoStart;if(elapsed===3)sim.fault(0,'heat');if(elapsed===12)sim.fault(1,'drop');if(elapsed===28){sim.fault(0,'recover');sim.fault(1,'recover');}if(elapsed===40){guided=false;sim.add('SYSTEM','Demo completed','All injected faults cleared. Live simulation continues.');}}sim.tick();render();}
function render(){
 $('clock').textContent=fmt(sim.time);$('pause').textContent=paused?'Resume':'Pause';$('live').textContent=paused?'Ⅱ SIMULATION PAUSED':'● LIVE SIMULATION';
 const healthy=sim.devices.filter(d=>d.status==='Healthy').length,online=sim.devices.filter(d=>sim.time-d.lastSeen<4).length,alerts=sim.devices.filter(d=>d.status!=='Healthy').length;
 $('summary').innerHTML=[['REPORTING',`${online}<small style="display:inline;font-size:15px"> / 3</small>`,'Fresh telemetry received','green'],['HEALTHY',healthy,'Devices within thresholds','green'],['NEEDS ATTENTION',alerts,'Devices with active conditions',alerts?'amber':'muted'],['SAMPLE INTERVAL','1<span style="font-size:15px">s</span>','Per device · simulation time','muted']].map(([a,b,c,d])=>`<div class="stat"><div class="stat-label">${a}</div><div class="number ${d}">${b}</div><p>${c}</p></div>`).join('');
 $('devices').innerHTML=sim.devices.map((d,i)=>{let stale=sim.time-d.lastSeen>=4;return `<button class="device ${selected===i?'selected':''}" data-device="${i}" aria-pressed="${selected===i}"><div><strong>${d.id}</strong><small>${d.name}</small><span class="badge ${color(d.status)}">${d.status}</span></div><div class="metric ${stale?'muted':d.temp>=80?'red':d.temp>=65?'amber':''}">${d.temp.toFixed(1)}°<small>${stale?'LAST KNOWN TEMP':'TEMPERATURE / °C'}</small></div><div class="metric ${d.battery<=20?'amber':''}">${Math.round(d.battery)}%<small>${stale?'LAST KNOWN BATTERY':'BATTERY'}</small></div><div class="metric heartbeat ${stale?'amber':'green'}">${sim.time-d.lastSeen}s<small>LAST RECEIVED</small></div></button>`;}).join('');
 const d=sim.devices[selected];$('chart-title').textContent=`${d.id} · Temperature`;$('chart-sub').textContent='Missing samples appear as gaps. Values are synthetic.';
 const y=v=>165-(v-20)/80*140;let path='',open=false;d.history.forEach((p,i)=>{if(p.temp===null){open=false;return;}path+=`${open?'L':'M'}${45+i/59*635},${y(p.temp)} `;open=true;});
 $('chart').innerHTML=[40,60,80,100].map(v=>`<line x1="45" y1="${y(v)}" x2="680" y2="${y(v)}" stroke="#2b3840"/><text x="8" y="${y(v)+4}" fill="#92a2ad" font-size="10">${v}°</text>`).join('')+`<line x1="45" y1="${y(65)}" x2="680" y2="${y(65)}" stroke="#eebd65" stroke-dasharray="5 5" opacity=".6"/><line x1="45" y1="${y(80)}" x2="680" y2="${y(80)}" stroke="#ff8585" stroke-dasharray="5 5" opacity=".8"/><path d="${path}" fill="none" stroke="#65e2b1" stroke-width="2.5"/><text x="45" y="187" fill="#92a2ad" font-size="10">${fmt(d.history[0]?.time||0)}</text><text x="635" y="187" fill="#92a2ad" font-size="10">${fmt(sim.time)}</text>`;
 const events=sim.events.filter(e=>$('filter').value==='all'||e.severity==='alert');$('event-count').textContent=`(${events.length})`;$('events').innerHTML=events.slice().reverse().map(e=>`<tr><td>${fmt(e.time)}</td><td>${e.device}</td><td class="${e.severity==='alert'?'amber':'green'}">${e.event}</td><td>${e.detail}</td></tr>`).join('')||'<tr><td colspan="4">No alerts recorded. Inject a fault or run the guided demo.</td></tr>';
 $('guide').textContent=guided?`Guided demo · ${sim.time-demoStart}/40s. At 3s: NODE-01 heats up. At 12s: NODE-02 disconnects. At 28s: both recover. Manual fault controls are disabled during replay.`:'Run the guided demo to replay a 40-second scenario: heat → disconnect → recovery. The demo resets the session.';
 $('demo').textContent=guided?'↻ Restart guided demo':'▶ Run guided demo';document.querySelectorAll('[data-fault]').forEach(b=>b.disabled=guided);
}
$('devices').onclick=e=>{const b=e.target.closest('[data-device]');if(b){selected=Number(b.dataset.device);$('target').value=selected;render();}};
$('target').onchange=()=>{selected=Number($('target').value);render();};
document.querySelectorAll('[data-fault]').forEach(b=>b.onclick=()=>{sim.fault(Number($('target').value),b.dataset.fault);render();});
$('pause').onclick=()=>{paused=!paused;render();};$('reset').onclick=reset;$('demo').onclick=()=>{reset();selected=0;$('target').value='0';guided=true;demoStart=sim.time;sim.add('SYSTEM','Guided demo started','40-second deterministic failure and recovery scenario.');render();};$('filter').onchange=render;
$('export').onclick=()=>{const rows=[['simulation_seconds','device','event','detail','severity'],...sim.events.map(e=>[e.time,e.device,e.event,e.detail,e.severity])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='relay-events.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
setInterval(()=>{for(let i=0;i<Number($('speed').value);i++)step();},1000);render();
